<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientPublicAllowAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientPublicAllowAccessor trait.
 *
 * Covers null default, string/VO assignment via withPublicAllow,
 * getPublicAllow/publicAllow accessors, and isPublicAllowChanged with/without original.
 */
class TrustedClientPublicAllowAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withPublicAllow creates a new instance with the PublicAllow set
     * from a string value, and getPublicAllow returns the primitive string.
     */
    public function testWithPublicAllowFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPublicAllowAccessorUnitTest();

        // Act
        $result = $holder->withPublicAllow(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isPublicAllow());
    }
    /**
     * Asserts that withpublicAllow has access to the value object
     * from a string value, and getPublicAllow returns the primitive string.
     */
    public function testWithPublicAllowFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPublicAllowAccessorUnitTest();

        // Act
        $result = $holder->withPublicAllow(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->publicAllow()->value());
    }
    public function testChangedPublicAllow(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientPublicAllowAccessorUnitTest()->withPublicAllow(true);
        $original = $holder->withPublicAllow(true);
        $same = $holder->withPublicAllow(true);
        $modified = $holder->withPublicAllow(false);

        // Act
        $withSame = $original->isPublicAllowChanged($same);
        $withDiferent = $original->isPublicAllowChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientPublicAllowAccessorUnitTest
{
    use TrustedClientPublicAllowAccessor;
}
